import { CreateProjectInput, CreateTaskInput, CreateUserInput, ProjectDto, TaskDto, TaskFilterInput, UserDto } from './dtos';
import { Project, Task, User } from '../domain/entities';
import { NotFoundError, ValidationError } from '../domain/errors';
import { IdGenerator, ProjectRepository, TaskRepository, UserRepository } from '../domain/repositories';

export class TaskManagementService {
  public constructor(
    private readonly users: UserRepository,
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
    private readonly ids: IdGenerator,
  ) {}

  public createUser(input: CreateUserInput): UserDto {
    const user = new User(this.ids.next(), input.name);
    this.users.save(user);
    return { id: user.id, name: user.name };
  }

  public createProject(input: CreateProjectInput): ProjectDto {
    const project = new Project(this.ids.next(), input.name);
    this.projects.save(project);
    return { id: project.id, name: project.name };
  }

  public createTask(input: CreateTaskInput): TaskDto {
    this.requireProject(input.projectId);
    if (input.assigneeId !== undefined && !this.users.findById(input.assigneeId)) {
      throw new NotFoundError('Assignee does not exist');
    }
    const dueDate = input.dueDate === undefined ? undefined : new Date(input.dueDate);
    if (dueDate !== undefined && Number.isNaN(dueDate.getTime())) {
      throw new ValidationError('Due date must be a valid ISO date');
    }
    const task = new Task(this.ids.next(), input.projectId, input.title, input.description, dueDate, input.assigneeId, input.status);
    this.tasks.save(task);
    return this.toTaskDto(task);
  }

  public listProjectTasks(projectId: string, filters: TaskFilterInput): TaskDto[] {
    this.requireProject(projectId);
    return this.tasks.findByProjectId(projectId, filters).map((task) => this.toTaskDto(task));
  }

  public markTaskDone(taskId: string): TaskDto {
    const task = this.tasks.findById(taskId);
    if (!task) throw new NotFoundError('Task does not exist');
    task.markDone();
    this.tasks.save(task);
    return this.toTaskDto(task);
  }

  private requireProject(id: string): void {
    if (!this.projects.findById(id)) throw new NotFoundError('Project does not exist');
  }

  private toTaskDto(task: Task): TaskDto {
    return { id: task.id, projectId: task.projectId, title: task.title, description: task.description,
      dueDate: task.dueDate?.toISOString(), status: task.status, assigneeId: task.assigneeId };
  }
}

